def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    parent = [-1] * n
    order = [0]
    for v in order:
        for u in adj[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    subtree_weight = w.copy()
    result = [0] * n

    for v in reversed(order):
        p = parent[v]
        if p != -1:
            subtree_weight[p] += subtree_weight[v]
            result[p] += result[v] + subtree_weight[v]

    total_weight = subtree_weight[0]
    for v in order:
        p = parent[v]
        if p != -1:
            result[v] = result[p] + total_weight - 2 * subtree_weight[v]

    return result
